import {DESIGNS} from './models/machine-designs.js';
const PARTS=['overview','spindle','table','control','toolchanger','axes','enclosure','conveyor'];
const names={overview:'Overview',spindle:'Spindle',table:'Worktable',control:'M80A control',toolchanger:'Tool magazine',axes:'Axis system',enclosure:'Enclosure',conveyor:'Chip handling'};
const glyph={cube:'<path d="m12 3 9 5v8l-9 5-9-5V8l9-5Zm0 10v8M3 8l9 5 9-5"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',left:'<path d="M19 12H5m5-5-5 5 5 5"/>',doors:'<path d="M3 4h8v16H3zM13 4h8v16h-8M8 10v4m8-4v4"/>',explode:'<path d="m12 3 7 4-7 4-7-4 7-4ZM5 12l7 4 7-4M5 17l7 4 7-4"/>',motion:'<path d="m9 5 11 7-11 7V5ZM3 5v14"/>',rotate:'<path d="M3 10a9 9 0 1 1 2 8M3 4v6h6"/>',wire:'<path d="m12 3 9 5v8l-9 5-9-5V8l9-5ZM3 8l18 8M21 8 3 16M12 3v18"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',reset:'<path d="M3 10a9 9 0 1 1 2 8M3 4v6h6"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m3 16 5-5 4 4 4-5 5 6"/>'};
const svg=id=>`<svg viewBox="0 0 24 24" aria-hidden="true">${glyph[id]||glyph.cube}</svg>`;
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const captions={'nano-x8':'Compact footprint. Serious capability.','nano-x10':'More travel. Compact thinking.','nv-855':'The foundation of your next breakthrough.','nv-1165':'Make room for greater possibilities.','nv-1270':'A bigger canvas for your ambition.','nv-1470':'More workspace. More possibilities.','nv-1670':'Room to build something bigger.'};
function spec(m,k){for(const s of m.specs)for(const [label,value] of s.rows)if(label===k)return value;return '—';}
export function componentInfo(m,id){
  const p={
    overview:{eyebrow:'MEET YOUR NEXT MACHINE',title:captions[m.id],text:DESIGNS[m.id].features.join(' · ')+'. Rotate the machine or open its doors to explore.',facts:[['X / Y / Z',m.travel.join(' × ')+' mm'],['TABLE LOAD',m.load],['TOOL MAGAZINE','24 tools']]},
    spindle:{eyebrow:'01 / SPINDLE ASSEMBLY',title:'12,000 RPM. Direct driven.',text:`The spindle assembly brings the tool to the workpiece. ${m.name} specifies ${spec(m,'Motor Power')} and a ${spec(m,'Taper / Diameter')} spindle taper / diameter.`,facts:[['SPINDLE SPEED','12,000 RPM'],['DRIVE',spec(m,'Drive Type')],['MOTOR',spec(m,'Motor Power')]]},
    table:{eyebrow:'02 / WORKTABLE',title:'The foundation of every part.',text:`A ${m.table} slotted table supports the workpiece and fixtures. The specified maximum table load for ${m.name} is ${m.load}.`,facts:[['TABLE SIZE',m.table],['MAX. LOAD',m.load],['T-SLOTS',spec(m,'T-Slot')]]},
    control:{eyebrow:'03 / OPERATOR CONTROL',title:'MITSUBISHI M80A.',text:'The operator interface brings program execution, axis positioning and tool management into one control. Explore the screen, jog controls and emergency stop.',facts:[['CNC SYSTEM','MITSUBISHI M80A'],['X / Y / Z',m.travel.join(' / ')+' mm'],['USB','Standard interface']]},
    toolchanger:{eyebrow:'04 / AUTOMATIC TOOL CHANGER',title:'24 positions. One workflow.',text:`An arm-type magazine stores 24 tools. The specified tool-to-tool change time for ${m.name} is ${spec(m,'Tool-to-Tool Timing')}. The exploded view reveals the carousel and exchange arm.`,facts:[['MAGAZINE','Arm-type · 24 tools'],['CHANGE TIME',spec(m,'Tool-to-Tool Timing')],['TOOL WEIGHT',spec(m,'Max. Tool Weight')]]},
    axes:{eyebrow:'05 / AXIS SYSTEM',title:'Precision in three dimensions.',text:`X, Y and Z travel is ${m.travel.join(' × ')} mm. The guideway, carriage and screw assemblies are shown in an explanatory layout so you can see how movement is organized.`,facts:[['X TRAVEL',m.travel[0]+' mm'],['Y TRAVEL',m.travel[1]+' mm'],['Z TRAVEL',m.travel[2]+' mm']]},
    enclosure:{eyebrow:'06 / MACHINE ENCLOSURE',title:DESIGNS[m.id].name,text:DESIGNS[m.id].description,facts:[['FOOTPRINT',spec(m,'Ground Clearance (L x W x H)')],['WEIGHT',m.weight],['SERIES',m.series]]},
    conveyor:{eyebrow:'07 / CHIP HANDLING',title:'Keep the process moving.',text:'Explore the model-specific chip chute, collection bin and conveyor arrangement. Optional accessories and their prices can be selected in the next quotation step.',facts:[['CONFIGURE IN','Accessories · step 02'],['ASSEMBLY','Reference visualization'],['OPTIONS','Machine-specific prices']]}
  };return p[id]||p.overview;
}

export function stageHTML(m,view='3d',{expanded=false}={}){
  return `<section class="machine-stage studio-stage ${view==='3d'?'is-3d':''} ${expanded?'expanded-stage':''}" data-view="${view}" aria-label="${m.name} interactive machine explorer">
    <div class="stage-top"><div class="explorer-caption"><span class="status-square"></span><div>THE MACHINE EXPLORER<small>${m.name} / <span class="model-detail-count">REFERENCE-BASED 3D</span></small></div></div><div class="stage-actions"><div class="view-switch" role="group" aria-label="Product view"><button data-exp="view" data-view="3d" class="${view==='3d'?'active':''}" aria-pressed="${view==='3d'}">${svg('cube')} 3D explorer</button><button data-exp="view" data-view="product" class="${view==='product'?'active':''}" aria-pressed="${view==='product'}">${svg('image')} Original photo</button></div>${expanded?'':`<button class="expand-explorer" data-exp="expand" aria-label="Expand machine explorer" title="Expand machine explorer">${svg('expand')}</button>`}</div></div>
    <div class="studio-watermark" aria-hidden="true">${m.name}</div><div class="floor-grid"></div><div class="orbit-ring"></div>
    <div class="stage-product ${view==='3d'?'hidden':''}" aria-hidden="${view==='3d'}"><img src="${m.image}" alt="Original ${m.name} product photograph"></div>
    <div class="scene-v2 ${view==='3d'?'active':''}" aria-label="${m.name} interactive 3D model"><div class="model-loading" role="status"><span></span>Preparing ${m.name} in 3D</div></div>
    <div class="view-axis" aria-hidden="true"><span>Z</span><i></i><b>X</b><small>Y</small></div>
    <div class="zoom-stack"><button data-exp="zoom-in" aria-label="Zoom in">${svg('plus')}</button><button data-exp="zoom-out" aria-label="Zoom out">${svg('minus')}</button><button data-exp="reset" aria-label="Reset machine view">${svg('reset')}</button></div>
    <div class="studio-view-tools"><div class="camera-presets" role="group" aria-label="Camera views">${[['iso','Isometric'],['front','Front'],['right','Side'],['rear','Rear']].map(([id,label])=>`<button data-exp="preset" data-preset="${id}" class="${id==='iso'?'active':''}" aria-pressed="${id==='iso'}">${label}</button>`).join('')}</div><div class="assembly-tools" role="group" aria-label="Machine inspection controls"><button data-exp="doors" aria-label="Open machine doors" title="Open machine doors" aria-pressed="false">${svg('doors')}<span>Open doors</span></button><button data-exp="explode" aria-label="Toggle exploded view" title="Exploded view" aria-pressed="false">${svg('explode')}<span>Exploded</span></button><button data-exp="motion" aria-label="Play motion study" title="Motion study" aria-pressed="false">${svg('motion')}<span>Motion</span></button><button data-exp="wire" aria-pressed="false" aria-label="Toggle wireframe" title="Wireframe">${svg('wire')}</button><button data-exp="rotate" aria-pressed="false" aria-label="Toggle automatic rotation" title="Auto rotation">${svg('rotate')}</button></div></div>
    <div class="component-inspector" aria-live="polite"></div>
    <div class="component-tabs" role="group" aria-label="Explore machine components">${PARTS.map((id,i)=>`<button data-exp="part" data-part="${id}" class="${i===0?'active':''}" aria-pressed="${i===0}">${i?`<small>${String(i).padStart(2,'0')}</small>`:svg('cube')}${names[id]}</button>`).join('')}</div>
    <div class="studio-disclaimer"><span>Drag to orbit · Arrow keys to rotate · + / − to zoom</span><span>Reference-based visualization · Interior layout illustrative</span></div>
  </section>`;
}

export function mountStage(root,machine,options={}){
  const stage=root.matches('.studio-stage')?root:root.querySelector('.studio-stage');
  const container=stage.querySelector('.scene-v2'),inspector=stage.querySelector('.component-inspector');
  let controller,disposed=false,selected='overview',view=stage.dataset.view;
  function showInfo(id){selected=id;if(id!=='overview')stage.querySelectorAll('[data-exp="preset"]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false');});const info=componentInfo(machine,id);inspector.innerHTML=`<div class="inspector-copy"><span>${info.eyebrow}</span><h3>${escape(info.title)}</h3><p>${escape(info.text)}</p></div><div class="inspector-facts">${info.facts.map(([k,v])=>`<div><small>${escape(k)}</small><strong>${escape(v)}</strong></div>`).join('')}</div><button class="next-component" data-exp="next" aria-label="Explore next component" title="Explore next component">${svg('arrow')}</button>`;stage.querySelectorAll('[data-exp="part"]').forEach(b=>{b.classList.toggle('active',b.dataset.part===id);b.setAttribute('aria-pressed',String(b.dataset.part===id));});const active=stage.querySelector('[data-exp="part"].active'),tabs=stage.querySelector('.component-tabs');if(active&&tabs)tabs.scrollTo({left:active.offsetLeft-tabs.clientWidth/2+active.clientWidth/2,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
  function sync(s){const map={doors:s.doors,explode:s.exploded,motion:s.motion,wire:s.wire,rotate:s.auto};for(const [action,active] of Object.entries(map)){const b=stage.querySelector(`[data-exp="${action}"]`);if(b){b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));if(action==='doors'){b.querySelector('span').textContent=active?'Close doors':'Open doors';b.setAttribute('aria-label',active?'Close machine doors':'Open machine doors');b.title=active?'Close machine doors':'Open machine doors';}if(action==='motion'){b.setAttribute('aria-label',active?'Pause motion study':'Play motion study');}}}stage.dataset.modelId=s.modelId;stage.dataset.modelParts=s.meshCount;stage.dataset.modelRevision=s.modelRevision;}
  showInfo('overview');
  const ready=(async()=>{
    try{const {createScene}=await import('./machine-explorer.js');if(disposed)return;controller=await createScene(container,machine,{onSelectPart:showInfo,onState:sync,onReady:()=>container.querySelector('.model-loading')?.remove()});if(disposed){controller.dispose();return;}stage.querySelector('.model-detail-count').textContent=controller.getState().meshCount+' MODELED DETAILS';if(view!=='3d'||document.querySelector('#studio-splash[open]'))controller.pause(true);}
    catch(error){if(!disposed){container.querySelector('.model-loading')?.remove();const msg=document.createElement('p');msg.className='scene-error';msg.textContent='The 3D model could not be loaded. The original product photo is available above.';container.append(msg);console.error('Machine explorer:',error);}}
  })();
  const onClick=e=>{const b=e.target.closest('[data-exp]');if(!b||!stage.contains(b))return;e.stopPropagation();const action=b.dataset.exp;
    if(action==='expand')return options.onExpand?.();
    if(action==='view'){view=b.dataset.view;stage.dataset.view=view;stage.classList.toggle('is-3d',view==='3d');container.classList.toggle('active',view==='3d');stage.querySelector('.stage-product').classList.toggle('hidden',view==='3d');stage.querySelector('.stage-product').setAttribute('aria-hidden',String(view==='3d'));stage.querySelectorAll('[data-exp="view"]').forEach(v=>{v.classList.toggle('active',v.dataset.view===view);v.setAttribute('aria-pressed',String(v.dataset.view===view));});controller?.pause(view!=='3d');options.onView?.(view);return;}
    if(!controller)return;
    if(['part','next'].includes(action)&&view!=='3d')stage.querySelector('[data-exp="view"][data-view="3d"]').click();
    if(action==='part')controller.selectPart(b.dataset.part);
    if(action==='next')controller.selectPart(PARTS[(PARTS.indexOf(selected)+1)%PARTS.length]);
    if(action==='doors')controller.toggleDoors();if(action==='explode')controller.toggleExploded();if(action==='motion')controller.toggleMotion();if(action==='wire')controller.toggleWire();if(action==='rotate')controller.toggleRotate();if(action==='zoom-in')controller.zoom(-1);if(action==='zoom-out')controller.zoom(1);
    if(action==='reset'){controller.reset();stage.querySelectorAll('[data-exp="preset"]').forEach(v=>{v.classList.toggle('active',v.dataset.preset==='iso');v.setAttribute('aria-pressed',String(v.dataset.preset==='iso'));});}
    if(action==='preset'){controller.preset(b.dataset.preset);stage.querySelectorAll('[data-exp="preset"]').forEach(v=>{v.classList.toggle('active',v===b);v.setAttribute('aria-pressed',String(v===b));});}
  };
  stage.addEventListener('click',onClick);
  return{ready,pause(value){controller?.pause(value||view!=='3d');},dispose(){disposed=true;stage.removeEventListener('click',onClick);controller?.dispose();}};
}

export function showSplash(machine,{onClose}={}){
  let old=document.querySelector('#studio-splash');if(old)return;
  const splash=document.createElement('dialog');splash.id='studio-splash';splash.className='studio-splash';splash.setAttribute('aria-labelledby','splash-heading');
  splash.innerHTML=`<div class="splash-shell"><header><a class="brand" href="#" aria-label="NANYA CNC"><img src="assets/logo.png" alt="NANYA CNC logo"><span>NANYA<span class="brand-cnc">CNC</span><small>PRECISION. WITHOUT LIMITS.</small></span></a><button class="splash-skip">Skip intro ${svg('arrow')}</button></header><div class="splash-layout"><div class="splash-copy"><div class="eyebrow"><span></span> NANYA / QUOTATION STUDIO 02</div><h1 id="splash-heading">Your next<br>advantage.<br><em>Engineered.</em></h1><p>Step inside the machine.<br>Shape what comes next.</p><button class="splash-enter" autofocus>Enter quotation studio ${svg('arrow')}</button><div class="splash-subtitle">EXPLORE. CONFIGURE. CREATE YOUR QUOTATION.</div></div><div class="splash-visual"><span class="splash-watermark" aria-hidden="true">PRECISION</span><div class="splash-orbit"></div><div class="splash-model"><img src="${machine.image}" alt="${machine.name} CNC machine"></div><div class="splash-model-label"><span>${machine.name}</span><small>3-AXIS VERTICAL MACHINING CENTER</small></div><div class="splash-corner-label"><span>12,000</span><small>RPM / DIRECT DRIVE</small></div></div></div><footer><div><strong>07</strong><span>INDIVIDUAL<br>MACHINE DESIGNS</span></div><div><strong>360°</strong><span>INTERACTIVE<br>EXPLORATION</span></div><div><strong>01</strong><span>STUDIO FOR<br>YOUR NEXT MOVE</span></div><span class="splash-footer-note">PRECISION STARTS WITH YOUR CHOICE.</span></footer></div>`;
  document.body.append(splash);splash.showModal();
  let introController,closed=false;const close=()=>{if(closed)return;closed=true;splash.classList.add('leaving');try{sessionStorage.setItem('nanya-studio-intro-v2','seen');}catch{}introController?.dispose();onClose?.();if(matchMedia('(prefers-reduced-motion: reduce)').matches){splash.close();splash.remove();}else setTimeout(()=>{splash.close();splash.remove();},350);};
  splash.querySelector('.splash-enter').addEventListener('click',close);splash.querySelector('.splash-skip').addEventListener('click',close);splash.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();close();});splash.addEventListener('cancel',e=>{e.preventDefault();close();});
  (async()=>{try{const {createScene}=await import('./machine-explorer.js');if(closed)return;const holder=splash.querySelector('.splash-model');introController=await createScene(holder,machine,{intro:true,onReady:()=>holder.querySelector('img')?.remove()});if(closed){introController.dispose();return;}}catch{}})();
}
